// Register.js
import { useState } from 'react';
import { FcGoogle } from 'react-icons/fc';
import { FaFacebook } from 'react-icons/fa';
import { AiOutlineEye, AiOutlineEyeInvisible, AiOutlineCheck } from 'react-icons/ai';
import { MdEmail, MdLock, MdPerson, MdClose } from 'react-icons/md';
import SocialLoginButtons from './SocialLoginButtons';

const Register = ({ onClose, switchToLogin }) => {
  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    email: '',
    password: '',
    confirmPassword: '',
    acceptTerms: false
  });
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const [passwordStrength, setPasswordStrength] = useState(0);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === 'checkbox' ? checked : value
    });

    // Vérifier la force du mot de passe
    if (name === 'password') {
      checkPasswordStrength(value);
    }

    setError('');
  };

  const checkPasswordStrength = (password) => {
    let strength = 0;
    if (password.length >= 6) strength++;
    if (password.length >= 8) strength++;
    if (/[A-Z]/.test(password)) strength++;
    if (/[0-9]/.test(password)) strength++;
    if (/[^A-Za-z0-9]/.test(password)) strength++;
    setPasswordStrength(strength);
  };

  const handleGoogleRegister = async () => {
    try {
      window.location.href = 'http://localhost:5000/api/auth/google';
    } catch (error) {
      console.error('Erreur Google registration:', error);
      setError('Erreur lors de l\'inscription avec Google');
    }
  };

  const handleFacebookRegister = async () => {
    try {
      window.location.href = 'http://localhost:5000/api/auth/facebook';
    } catch (error) {
      console.error('Erreur Facebook registration:', error);
      setError('Erreur lors de l\'inscription avec Facebook');
    }
  };

  const validateForm = () => {
    const errors = [];

    if (!formData.first_name.trim()) errors.push('Le prénom est requis');
    if (!formData.last_name.trim()) errors.push('Le nom est requis');

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) errors.push('Email invalide');

    if (formData.password.length < 6) errors.push('Le mot de passe doit contenir au moins 6 caractères');
    if (formData.password !== formData.confirmPassword) errors.push('Les mots de passe ne correspondent pas');
    if (!formData.acceptTerms) errors.push('Vous devez accepter les conditions d\'utilisation');

    return errors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    const errors = validateForm();
    if (errors.length > 0) {
      setError(errors.join(', '));
      setLoading(false);
      return;
    }

    try {
      const { confirmPassword, acceptTerms, ...submitData } = formData;

      const response = await fetch('http://localhost:5000/api/auth/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify(submitData),
      });

      const data = await response.json();

      if (data.success) {
        // Stockage du token et des données utilisateur
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));

        // Message de succès
        setSuccess(true);
        const event = new CustomEvent('authSuccess', { 
          detail: { 
            message: 'Inscription réussie ! Bienvenue !',
            user: data.user 
          } 
        });
        window.dispatchEvent(event);

        // Redirection après 2 secondes
        setTimeout(() => {
          onClose();
          window.location.href = '/dashboard';
        }, 2000);
      } else {
        setError(data.message || 'Erreur lors de l\'inscription');
      }
    } catch (error) {
      console.error('Erreur d\'inscription:', error);
      setError('Erreur de connexion au serveur. Veuillez réessayer.');
    } finally {
      setLoading(false);
    }
  };

  const getPasswordStrengthColor = () => {
    if (passwordStrength <= 2) return 'bg-red-500';
    if (passwordStrength <= 3) return 'bg-yellow-500';
    return 'bg-green-500';
  };

  const getPasswordStrengthText = () => {
    if (passwordStrength <= 2) return 'Faible';
    if (passwordStrength <= 3) return 'Moyen';
    return 'Fort';
  };

  return (
    <div className="p-6 md:p-8">
      {/* En-tête */}
      <div className="flex justify-between items-center mb-6">
        <div>
          <h3 className="text-2xl font-bold bg-gradient-to-r from-green-600 to-emerald-500 bg-clip-text text-transparent">
            Inscription
          </h3>
          <p className="text-sm text-gray-500 mt-1">
            Créez votre compte en 30 secondes
          </p>
        </div>
        <button
          onClick={onClose}
          className="p-2 hover:bg-gray-100 rounded-full transition duration-200"
          aria-label="Fermer"
        >
          <MdClose className="text-gray-500 text-xl" />
        </button>
      </div>

      <div className="space-y-6">
        {/* Message de succès */}
        {success && (
          <div className="animate-fadeIn bg-green-50 border border-green-200 rounded-xl p-4">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <AiOutlineCheck className="h-5 w-5 text-green-400" />
              </div>
              <div className="ml-3">
                <p className="text-sm font-medium text-green-800">
                  Inscription réussie ! Redirection en cours...
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Boutons d'inscription sociale */}
        <SocialLoginButtons
          onGoogleLogin={handleGoogleRegister}
          onFacebookLogin={handleFacebookRegister}
          action="register"
        />

        {/* Séparateur */}
        <div className="relative">
          <div className="absolute inset-0 flex items-center">
            <div className="w-full border-t border-gray-200"></div>
          </div>
          <div className="relative flex justify-center text-sm">
            <span className="px-4 bg-white text-gray-500">Ou inscrivez-vous par email</span>
          </div>
        </div>

        {/* Message d'erreur */}
        {error && !success && (
          <div className="animate-fadeIn bg-red-50 border border-red-200 rounded-xl p-4">
            <div className="flex items-center">
              <div className="flex-shrink-0">
                <svg className="h-5 w-5 text-red-400" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                </svg>
              </div>
              <div className="ml-3">
                <p className="text-sm font-medium text-red-800">{error}</p>
              </div>
            </div>
          </div>
        )}

        {/* Formulaire */}
        <form onSubmit={handleSubmit} className="space-y-5">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Prénom
              </label>
              <div className="relative group">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <MdPerson className="text-gray-400 group-focus-within:text-green-500 transition-colors" />
                </div>
                <input
                  type="text"
                  name="first_name"
                  value={formData.first_name}
                  onChange={handleChange}
                  className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-500 focus:border-green-500 transition duration-300 placeholder-gray-400"
                  placeholder="Votre prénom"
                  required
                  disabled={loading || success}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Nom
              </label>
              <div className="relative group">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <MdPerson className="text-gray-400 group-focus-within:text-green-500 transition-colors" />
                </div>
                <input
                  type="text"
                  name="last_name"
                  value={formData.last_name}
                  onChange={handleChange}
                  className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-500 focus:border-green-500 transition duration-300 placeholder-gray-400"
                  placeholder="Votre nom"
                  required
                  disabled={loading || success}
                />
              </div>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Adresse email
            </label>
            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MdEmail className="text-gray-400 group-focus-within:text-green-500 transition-colors" />
              </div>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-500 focus:border-green-500 transition duration-300 placeholder-gray-400"
                placeholder="exemple@email.com"
                required
                disabled={loading || success}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">
              Mot de passe
            </label>
            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MdLock className="text-gray-400 group-focus-within:text-green-500 transition-colors" />
              </div>
              <input
                type={showPassword ? 'text' : 'password'}
                name="password"
                value={formData.password}
                onChange={handleChange}
                className="w-full pl-10 pr-12 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-green-500 focus:border-green-500 transition duration-300 placeholder-gray-400"
                placeholder="Créez un mot de passe sécurisé"
                required
                disabled={loading || success}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute inset-y-0 right-0 pr-3 flex items-center hover:bg-gray-50 rounded-r-xl p-1"
                disabled={loading || success}
              >
                {showPassword ? (
                  <AiOutlineEyeInvisible className="text-gray-400 hover:text-gray-600" />
                ) : (
                  <AiOutlineEye className="text-gray-400 hover:text-gray-600" />
                )}
              </button>
            </div>

            {/* Indicateur de force du mot de passe */}
            {formData.password && (
              <div className="space-y-1">
                <div className="flex justify-between text-xs">
                  <span className="text-gray-500">Force du mot de passe:</span>
                  <span className={`font-medium ${
                    passwordStrength <= 2 ? 'text-red-600' :
                    passwordStrength <= 3 ? 'text-yellow-600' :
                    'text-green-600'
                  }`}>
                    {getPasswordStrengthText()}
                  </span>
                </div>
                <div className="h-1.5 w-full bg-gray-200 rounded-full overflow-hidden">
                  <div 
                    className={`h-full ${getPasswordStrengthColor()} transition-all duration-300`}
                    style={{ width: `${(passwordStrength / 5) * 100}%` }}
                  />
                </div>
                <ul className="text-xs text-gray-500 space-y-1 mt-2">
                  <li className="flex items-center">
                    <AiOutlineCheck className={`mr-1 ${formData.password.length >= 6 ? 'text-green-500' : 'text-gray-300'}`} />
                    Au moins 6 caractères
                  </li>
                  <li className="flex items-center">
                    <AiOutlineCheck className={`mr-1 ${/[A-Z]/.test(formData.password) ? 'text-green-500' : 'text-gray-300'}`} />
                    Une majuscule
                  </li>
                  <li className="flex items-center">
                    <AiOutlineCheck className={`mr-1 ${/[0-9]/.test(formData.password) ? 'text-green-500' : 'text-gray-300'}`} />
                    Un chiffre
                  </li>
                </ul>
              </div>
            )}
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Confirmer le mot de passe
            </label>
            <div className="relative group">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <MdLock className="text-gray-400 group-focus-within:text-green-500 transition-colors" />
              </div>
              <input
                type={showConfirmPassword ? 'text' : 'password'}
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                className={`w-full pl-10 pr-12 py-3 border rounded-xl focus:ring-2 focus:ring-green-500 focus:border-green-500 transition duration-300 placeholder-gray-400 ${
                  formData.password && formData.confirmPassword && formData.password !== formData.confirmPassword
                    ? 'border-red-300'
                    : 'border-gray-300'
                }`}
                placeholder="Confirmez votre mot de passe"
                required
                disabled={loading || success}
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                className="absolute inset-y-0 right-0 pr-3 flex items-center hover:bg-gray-50 rounded-r-xl p-1"
                disabled={loading || success}
              >
                {showConfirmPassword ? (
                  <AiOutlineEyeInvisible className="text-gray-400 hover:text-gray-600" />
                ) : (
                  <AiOutlineEye className="text-gray-400 hover:text-gray-600" />
                )}
              </button>
            </div>
            {formData.password && formData.confirmPassword && formData.password !== formData.confirmPassword && (
              <p className="mt-1 text-sm text-red-600">Les mots de passe ne correspondent pas</p>
            )}
          </div>

          {/* Conditions */}
          <label className="flex items-start space-x-3 cursor-pointer">
            <input
              type="checkbox"
              name="acceptTerms"
              checked={formData.acceptTerms}
              onChange={handleChange}
              className="mt-0.5 w-4 h-4 rounded border-gray-300 text-green-600 focus:ring-green-500 focus:ring-offset-0"
              required
              disabled={loading || success}
            />
            <span className="text-sm text-gray-600">
              J'accepte les{' '}
              <a href="/terms" className="font-medium text-green-600 hover:text-green-700 transition duration-200">
                conditions d'utilisation
              </a>{' '}
              et la{' '}
              <a href="/privacy" className="font-medium text-green-600 hover:text-green-700 transition duration-200">
                politique de confidentialité
              </a>
            </span>
          </label>

          {/* Bouton de soumission */}
          <button
            type="submit"
            disabled={loading || success}
            className="w-full bg-gradient-to-r from-green-600 to-emerald-500 text-white py-3.5 rounded-xl font-semibold hover:shadow-lg transform hover:-translate-y-0.5 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:transform-none"
          >
            {loading ? (
              <div className="flex items-center justify-center">
                <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent mr-3"></div>
                Inscription en cours...
              </div>
            ) : success ? (
              <div className="flex items-center justify-center">
                <AiOutlineCheck className="mr-2" />
                Inscription réussie !
              </div>
            ) : (
              "S'inscrire gratuitement"
            )}
          </button>
        </form>

        {/* Lien vers connexion */}
        <div className="text-center pt-4 border-t border-gray-100">
          <p className="text-sm text-gray-600">
            Déjà un compte ?{' '}
            <button
              type="button"
              onClick={switchToLogin}
              className="font-semibold text-green-600 hover:text-green-700 transition duration-200 inline-flex items-center"
              disabled={loading || success}
            >
              Se connecter
              <svg className="w-4 h-4 ml-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
              </svg>
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Register;
